Example//Java Program to use nested while loop in Java
public class Main {  
public static void main(String[] args) {  
    int i=1;
    //outer while loop
    while(i<=3){  
        //inner while loop
        int j=1;
        while(j<=5){
            System.out.println(i+" "+j);  
            j++;  
        }  
    i++;
    }
}  
}  
